{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table demand_plan_v2 as WITH MONTH_DATA AS ( SELECT CAST(DATE_TRUNC(\'MONTH\', DATEADD(MONTH, ROW_NUMBER() OVER (ORDER BY SEQ4()), \'2024-03-01\')) AS DATE) AS MONTH_START FROM TABLE(GENERATOR(ROWCOUNT => 120)) ), date_params AS ( SELECT CURRENT_DATE() AS current_date, MONTH(CURRENT_DATE()) AS current_month, LAST_DAY(CURRENT_DATE()) AS month_end_date, LAST_DAY(CURRENT_DATE()) AS last_day_of_the_month, DAY(LAST_DAY(CURRENT_DATE())) AS total_days_in_month, DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AS first_day_of_month, DAY(LAST_DAY(CURRENT_DATE())) - DAY(CURRENT_DATE()) + 1 AS days_left_in_month ), category_mapping AS ( SELECT DISTINCT UPPER(CATEGORY) AS CATEGORY, UPPER(L1_CATEGORY) AS L1_CATEGORY, SUM(ONLINE_INVENTORY) AS WH_INV FROM SNITCH_DB.MAPLEMONK.CATEGORY_JOURNEY GROUP BY UPPER(CATEGORY), UPPER(L1_CATEGORY) ), dataframe AS ( SELECT m.MONTH_START, c.CATEGORY, c.L1_CATEGORY, c.WH_INV FROM MONTH_DATA m CROSS JOIN category_mapping c ORDER BY m.MONTH_START, c.CATEGORY ), online_cat_mix_data AS ( SELECT UPPER(L1_CATEGORY) AS L1_CATEGORY, UPPER(CATEGORY) AS CATEGORY, TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, ONLINE_CAT_MIX AS ONLINE_CAT_MIX FROM SNITCH_DB.MAPLEMONK.google_sheet_online_cat_mix WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), offline_cat_mix_data AS ( SELECT UPPER(L1_CATEGORY) AS L1_CATEGORY, UPPER(CATEGORY) AS CATEGORY, TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, OFFLINE_CAT_MIX AS OFFLINE_CAT_MIX FROM SNITCH_DB.MAPLEMONK.google_sheet_offline_cat_mix WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), fresh_moq_data AS ( SELECT TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, UPPER(L1_CATEGORY) AS L1_CATEGORY, UPPER(CATEGORY) AS CATEGORY, MOQ AS FRESH_MOQ FROM SNITCH_DB.MAPLEMONK.google_sheet_fresh_moq WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), repeat_moq_data AS ( SELECT UPPER(L1_CATEGORY) AS L1_CATEGORY, UPPER(CATEGORY) AS CATEGORY, \"REPEAT\" AS REPEAT_MOQ, TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START FROM SNITCH_DB.MAPLEMONK.google_sheet_repeat_moq WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), material_perc_data AS ( SELECT UPPER(\"MATERIAL\") AS MATERIAL, UPPER(\"CATEGORY\") AS CATEGORY, TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, \"MATERIAL_PERC\" AS MATERIAL_PERC FROM SNITCH_DB.MAPLEMONK.google_sheet_material_perc WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE) ), nso_replen_data AS ( SELECT TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, CASE WHEN TO_DATE(MONTH, \'DD/MM/YYYY\') = (SELECT first_day_of_month FROM date_params) THEN NSO * (SELECT days_left_in_month FROM date_params) / (SELECT total_days_in_month FROM date_params) ELSE NSO END AS NSO, CASE WHEN TO_DATE(MONTH, \'DD/MM/YYYY\') = (SELECT first_day_of_month FROM date_params) THEN CAST(REPLACE(REPLEN,\',\', \'\') AS FLOAT) * (SELECT days_left_in_month FROM date_params) / (SELECT total_days_in_month FROM date_params) ELSE CAST(REPLACE(REPLEN,\',\', \'\') AS FLOAT) END AS REPLEN FROM SNITCH_DB.MAPLEMONK.google_sheet_nso_replen WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), inwards_data AS ( SELECT UPPER(\"L1_CATEGORY\") AS L1_CATEGORY, UPPER(\"CATEGORY\") AS CATEGORY, TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, CASE WHEN TO_DATE(MONTH, \'DD/MM/YYYY\') = (SELECT first_day_of_month FROM date_params) THEN INWARDS * (SELECT days_left_in_month FROM date_params) / (SELECT total_days_in_month FROM date_params) ELSE INWARDS END AS INWARDS FROM SNITCH_DB.MAPLEMONK.google_sheet_inwards_projection WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), sor_data AS ( SELECT TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, CASE WHEN TO_DATE(MONTH, \'DD/MM/YYYY\') = (SELECT first_day_of_month FROM date_params) THEN SOR * (SELECT days_left_in_month FROM date_params) / (SELECT total_days_in_month FROM date_params) ELSE SOR END AS SOR FROM SNITCH_DB.MAPLEMONK.google_sheet_SOR WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) ), category_distribution AS ( SELECT * FROM (VALUES (\'CARGO PANTS\', \'SNITCH\', .0395), (\'CHINOS\', \'SNITCH\', .0150), (\'JEANS\', \'SNITCH\', .2645), (\'OVERSHIRT\', \'SNITCH\', .0200), (\'SHIRTS\', \'SNITCH\', .4861), (\'TROUSERS\', \'SNITCH\', .0809), (\'T-SHIRTS\', \'SNITCH\', .0940) ) AS t(CATEGORY, L1_CATEGORY, PERCENTAGE) ), all_categories AS ( SELECT DISTINCT CATEGORY, l1_category FROM category_mapping ), sor_mix AS ( SELECT d.MONTH_START, c.CATEGORY, c.L1_CATEGORY, COALESCE(d.SOR, 0) * COALESCE(cd.PERCENTAGE, 0) AS CATEGORY_SOR FROM all_categories c LEFT JOIN sor_data d LEFT JOIN category_distribution cd ON c.CATEGORY = cd.CATEGORY AND c.L1_CATEGORY = cd.L1_CATEGORY ), curr_sales AS ( SELECT SUM(\"SHOPIFY_RETURNS30\") AS SHOPIFY_RETURNS30, SUM(\"MARKETPLACE_RETURNS30\") AS MARKETPLACE_RETURNS30, SUM(\"SHOPIFY_QUANT30\") AS SHOPIFY_QUANT30, SUM(\"MP_QUANT30\") AS MP_QUANT30, FROM snitch_db.maplemonk.category_journey ), sales_data AS ( SELECT (1 - (SUM(SHOPIFY_RETURNS30) + SUM(MARKETPLACE_RETURNS30)) / NULLIF(SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30), 0)) * (SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30)) AS ORIGINAL_SALES, CASE WHEN CURRENT_DATE BETWEEN (SELECT first_day_of_month FROM date_params) AND (SELECT last_day_of_the_month FROM date_params) THEN (1 - (SUM(SHOPIFY_RETURNS30) + SUM(MARKETPLACE_RETURNS30)) / NULLIF(SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30), 0)) * (SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30)) * (SELECT days_left_in_month FROM date_params) / NULLIF((SELECT total_days_in_month FROM date_params), 0) ELSE (1 - (SUM(SHOPIFY_RETURNS30) + SUM(MARKETPLACE_RETURNS30)) / NULLIF(SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30), 0)) * (SUM(SHOPIFY_QUANT30) + SUM(MP_QUANT30)) END AS CURRENT_SALES FROM curr_sales ), online_sales_data AS ( SELECT TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, CASE WHEN TO_DATE(MONTH, \'DD/MM/YYYY\') = DATE_TRUNC(\'MONTH\', CURRENT_DATE) THEN (SELECT CURRENT_SALES FROM sales_data) ELSE SALES / 1200 END AS ONLINE_SALES FROM SNITCH_DB.MAPLEMONK.google_sheet_sales WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE) ), --sunset AS ( -- SELECT -- sunset, -- UPPER(\"L1_CATEGORY\") AS L1_CATEGORY, -- UPPER(\"CATEGORY\") AS CATEGORY, -- TO_DATE(MONTH, \'DD/MM/YYYY\') AS MONTH_START, -- FROM SNITCH_DB.MAPLEMONK.google_sheet_sor_mix_doi -- WHERE TO_DATE(MONTH, \'DD/MM/YYYY\') >= (SELECT first_day_of_month FROM date_params) --), fixed_data AS ( SELECT a.MONTH_START, a.CATEGORY, a.L1_CATEGORY, a.WH_INV, b.online_cat_mix, c.offline_cat_mix, d.fresh_moq, e.repeat_moq, (f.replen * c.Offline_Cat_Mix)AS replen, (f.NSO * c.Offline_Cat_Mix) AS NSO, g.inwards, h.CATEGORY_SOR AS sor, (i.ONLINE_SALES * b.Online_Cat_Mix) AS SALES, --j.sunset, k.\"Target DOI\" AS TARGET_DOI FROM dataframe AS a JOIN online_cat_mix_data b ON a.L1_CATEGORY = UPPER(b.L1_CATEGORY) AND a.CATEGORY =UPPER( b.CATEGORY) AND a.MONTH_START = b.MONTH_START JOIN offline_cat_mix_data c ON a.L1_CATEGORY = UPPER(c.L1_CATEGORY) AND a.CATEGORY = UPPER(c.CATEGORY) AND a.MONTH_START = c.MONTH_START JOIN fresh_moq_data d ON a.L1_CATEGORY = UPPER(d.L1_CATEGORY) AND a.CATEGORY = UPPER(d.CATEGORY) AND a.MONTH_START = d.MONTH_START JOIN repeat_moq_data e ON a.L1_CATEGORY = UPPER(e.L1_CATEGORY) AND a.CATEGORY = UPPER(e.CATEGORY) AND a.MONTH_START = e.MONTH_START JOIN nso_replen_data f ON a.MONTH_START = f.MONTH_START JOIN inwards_data g ON a.L1_CATEGORY = UPPER(g.L1_CATEGORY) AND a.CATEGORY = UPPER(g.CATEGORY) AND a.MONTH_START = g.MONTH_START LEFT JOIN sor_mix h ON a.L1_CATEGORY = UPPER(h.L1_CATEGORY) AND a.CATEGORY = UPPER(h.CATEGORY) AND a.MONTH_START = h.MONTH_START JOIN online_sales_data i ON a.MONTH_START = i.MONTH_START --JOIN google_sheet_sor_mix_doi j --ON a.L1_CATEGORY = j.L1_CATEGORY AND a.CATEGORY = j.CATEGORY AND a.MONTH_START = j.MONTH_START --WHERE a.MONTH_START >= DATE_TRUNC(\'MONTH\', CURRENT_DATE) JOIN gs__online_cat_mix k ON a.L1_CATEGORY = UPPER(k.\"L1 Category\") AND a.CATEGORY = UPPER(k.\"CATEGORY\") WHERE a.MONTH_START >= DATE_TRUNC(\'MONTH\', CURRENT_DATE) ), monthly_inw_data AS ( SELECT MONTH_START, CATEGORY, L1_CATEGORY, WH_INV, online_cat_mix, target_doi, offline_cat_mix, fresh_moq, repeat_moq, NSO, Replen, inwards, sor, sales, CASE WHEN LOWER(CATEGORY) IN (\'hoodies\', \'sweaters\') THEN 0 ELSE 1 END AS sunset, LEAD(inwards, 1) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_1_Inwards, LEAD(Sales, 1) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_1_ONLINE_SALES, LEAD(NSO, 1) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_1, LEAD(Replen, 1) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_1, LEAD(SOR, 1) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_1, LEAD(Sales, 2) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_2_ONLINE_SALES, LEAD(NSO, 2) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_2, LEAD(Replen, 2) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_2, LEAD(SOR, 2) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_2, LEAD(Sales, 3) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_3_ONLINE_SALES, LEAD(NSO, 3) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_3, LEAD(Replen, 3) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_3, LEAD(SOR, 3) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_3, LEAD(Sales, 4) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_4_ONLINE_SALES, LEAD(NSO, 4) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_4, LEAD(Replen, 4) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_4, LEAD(SOR, 4) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_4, LEAD(Sales, 5) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_5_ONLINE_SALES, LEAD(NSO, 5) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_5, LEAD(Replen, 5) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_5, LEAD(SOR, 5) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_5, LEAD(Sales, 6) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_6_ONLINE_SALES, LEAD(NSO, 6) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_6, LEAD(Replen, 6) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_6, LEAD(SOR, 6) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_6, LEAD(Sales, 7) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS CM_PLUS_7_ONLINE_SALES, LEAD(NSO, 7) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS NSO_CM_PLUS_7, LEAD(Replen, 7) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS Replen_CM_PLUS_7, LEAD(SOR, 7) OVER (PARTITION BY CATEGORY, L1_CATEGORY ORDER BY MONTH_START) AS SOR_CM_PLUS_7 FROM fixed_data ), opening_cm_plus_2 AS ( SELECT *, GREATEST(WH_INV + INWARDS + CM_PLUS_1_INWARDS - CM_PLUS_1_ONLINE_SALES - SALES - NSO - NSO_CM_PLUS_1 - REPLEN - REPLEN_CM_PLUS_1 - SOR_CM_PLUS_2, 0) AS OPENING_PLUS_2 FROM monthly_inw_data ), dwi_cm_plus_2 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_2 - CM_PLUS_2_ONLINE_SALES - NSO_CM_PLUS_2 - REPLEN_CM_PLUS_2 - SOR_CM_PLUS_2) / NULLIF(CM_PLUS_2_ONLINE_SALES, 0),0) AS DWI_PLUS_2 FROM OPENING_CM_PLUS_2 ), inwards_cm_plus_2 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_2) * CM_PLUS_2_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_2 FROM dwi_cm_plus_2 ), opening_cm_plus_3 AS ( SELECT *, GREATEST((OPENING_PLUS_2 + INWARDS_PROJ_CM_PLUS_2) - (CM_PLUS_2_Online_Sales + NSO_CM_PLUS_2 + Replen_CM_PLUS_2 + SOR_CM_PLUS_3), 0) AS OPENING_PLUS_3 FROM inwards_cm_plus_2 ), dwi_cm_plus_3 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_3 - CM_PLUS_3_ONLINE_SALES - NSO_CM_PLUS_3 - REPLEN_CM_PLUS_3 - SOR_CM_PLUS_3) / NULLIF(CM_PLUS_3_ONLINE_SALES, 0), 0) AS DWI_PLUS_3 FROM OPENING_CM_PLUS_3 ), inwards_cm_plus_3 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_3) * CM_PLUS_3_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_3 FROM dwi_cm_plus_3 ), opening_cm_plus_4 AS ( SELECT *, GREATEST((opening_plus_3 + INWARDS_PROJ_CM_PLUS_3 ) - (CM_PLUS_3_Online_Sales + NSO_CM_PLUS_3 + Replen_CM_PLUS_3 + SOR_CM_PLUS_3), 0) AS OPENING_PLUS_4 FROM inwards_cm_plus_3 ), dwi_cm_plus_4 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_4 - CM_PLUS_4_ONLINE_SALES - NSO_CM_PLUS_4 - REPLEN_CM_PLUS_4 - SOR_CM_PLUS_4) / NULLIF(CM_PLUS_4_ONLINE_SALES, 0), 0) AS DWI_PLUS_4 FROM OPENING_CM_PLUS_4 ), inwards_cm_plus_4 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_4) * CM_PLUS_4_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_4 FROM dwi_cm_plus_4 ), opening_cm_plus_5 AS ( SELECT *, GREATEST((OPENING_PLUS_4 + INWARDS_PROJ_CM_PLUS_4) - (CM_PLUS_4_Online_Sales + NSO_CM_PLUS_4 + Replen_CM_PLUS_4 + SOR_CM_PLUS_4), 0) AS OPENING_PLUS_5 FROM inwards_cm_plus_4 ), dwi_cm_plus_5 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_5 - CM_PLUS_5_ONLINE_SALES - NSO_CM_PLUS_5 - REPLEN_CM_PLUS_5 - SOR_CM_PLUS_5) / NULLIF(CM_PLUS_5_ONLINE_SALES, 0), 0) AS DWI_PLUS_5 FROM OPENING_CM_PLUS_5 ), inwards_cm_plus_5 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_5) * CM_PLUS_5_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_5 FROM dwi_cm_plus_5 ), opening_cm_plus_6 AS ( SELECT *, GREATEST((OPENING_PLUS_5 + INWARDS_PROJ_CM_PLUS_5) - (CM_PLUS_5_Online_Sales + NSO_CM_PLUS_5 + Replen_CM_PLUS_5 + SOR_CM_PLUS_5), 0) AS OPENING_PLUS_6 FROM inwards_cm_plus_5 ), dwi_cm_plus_6 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_6 - CM_PLUS_6_ONLINE_SALES - NSO_CM_PLUS_6 - REPLEN_CM_PLUS_6 - SOR_CM_PLUS_6) / NULLIF(CM_PLUS_6_ONLINE_SALES, 0), 0) AS DWI_PLUS_6 FROM OPENING_CM_PLUS_6 ), inwards_cm_plus_6 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_6) * CM_PLUS_6_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_6 FROM dwi_cm_plus_6 ), opening_cm_plus_7 AS ( SELECT *, GREATEST((OPENING_PLUS_6 + INWARDS_PROJ_CM_PLUS_6) - ( CM_PLUS_6_Online_Sales + NSO_CM_PLUS_6 + Replen_CM_PLUS_6 + SOR_CM_PLUS_6), 0) AS OPENING_PLUS_7 FROM inwards_cm_plus_6 ), dwi_cm_plus_7 AS ( SELECT *, GREATEST(31* (OPENING_PLUS_7 - CM_PLUS_7_ONLINE_SALES - NSO_CM_PLUS_7 - REPLEN_CM_PLUS_7 - SOR_CM_PLUS_7) / NULLIF(CM_PLUS_7_ONLINE_SALES, 0), 0) AS DWI_PLUS_7 FROM OPENING_CM_PLUS_7 ), inwards_cm_plus_7 AS ( SELECT *, GREATEST((TARGET_DOI - DWI_PLUS_7) * CM_PLUS_7_ONLINE_SALES / 30, 0) * sunset AS INWARDS_PROJ_CM_PLUS_7 FROM dwi_cm_plus_7 ) SELECT MONTH_START, L1_CATEGORY, CATEGORY, SALES AS ONLINE_SALES, NSO, INWARDS, CM_PLUS_1_Inwards, INWARDS_PROJ_CM_PLUS_2, INWARDS_PROJ_CM_PLUS_3, INWARDS_PROJ_CM_PLUS_4, INWARDS_PROJ_CM_PLUS_5, INWARDS_PROJ_CM_PLUS_6, INWARDS_PROJ_CM_PLUS_7, CM_PLUS_1_ONLINE_SALES, CM_PLUS_2_ONLINE_SALES, CM_PLUS_3_ONLINE_SALES, CM_PLUS_4_ONLINE_SALES, CM_PLUS_5_ONLINE_SALES, CM_PLUS_6_ONLINE_SALES, CM_PLUS_7_ONLINE_SALES, NSO_CM_PLUS_1, NSO_CM_PLUS_2, NSO_CM_PLUS_3, NSO_CM_PLUS_4, NSO_CM_PLUS_5, NSO_CM_PLUS_6, NSO_CM_PLUS_7, OPENING_PLUS_2, OPENING_PLUS_3, OPENING_PLUS_4, OPENING_PLUS_5, OPENING_PLUS_6, OPENING_PLUS_7, REPLEN_CM_PLUS_1, REPLEN_CM_PLUS_2, REPLEN_CM_PLUS_3, REPLEN_CM_PLUS_4, REPLEN_CM_PLUS_5, REPLEN_CM_PLUS_6, REPLEN_CM_PLUS_7, SOR_CM_PLUS_1, SOR_CM_PLUS_2, SOR_CM_PLUS_3, SOR_CM_PLUS_4, SOR_CM_PLUS_5, SOR_CM_PLUS_6, SOR_CM_PLUS_7, FROM inwards_cm_plus_7 WHERE month_start= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            